-- Four new uploaded products; four repeated photos already exist. No prices supplied.
begin;
insert into public.products(id,store_id,name,description,price,image,section,available,translations)
select r.id,s.id,r.name,r.description,null,r.image,r.section,true,r.translations
from jsonb_to_recordset($products$[{"id": "d846f3c7-395e-5a4c-a569-e64b21df1a74", "name": "تشكيلة طناجر طهي وصواني بألوان متعددة", "description": "طناجر بأغطية ومقابض وأحجام وألوان متنوعة، مع صواني طهي كما تظهر في الصورة.", "section": "أدوات مطبخ", "image": "https://damascus-shop.com/images/happy-house/20261101/29964.jpg", "translations": {"en": {"name": "Assorted colourful cooking pots and pans"}, "de": {"name": "Verschiedene farbige Kochtöpfe und Backformen"}}}, {"id": "8d654279-c04b-5b32-bfdc-2e3c5dbed7b6", "name": "طقم ضيافة أزرق بنقشة الزهور", "description": "فناجين وصحون وأوعية بمقابض باللون الأزرق ونقوش زهور بيضاء، مع طبق بغطاء متناسق.", "section": "أدوات ضيافة", "image": "https://damascus-shop.com/images/happy-house/20261101/29962.jpg", "translations": {"en": {"name": "Blue floral serving set"}, "de": {"name": "Blaues Servierset mit Blumenmuster"}}}, {"id": "8e2b8a4c-e48f-5f5a-8b0f-5c3d083f19fd", "name": "طقم فناجين أبيض بخطوط ذهبية وصحون داكنة", "description": "فناجين بيضاء بخطوط زخرفية ذهبية، مع صحون بحواف داكنة ونقوش متناسقة كما في الصورة.", "section": "أدوات ضيافة", "image": "https://damascus-shop.com/images/happy-house/20261101/29956.jpg", "translations": {"en": {"name": "White cups with gold lines and dark saucers"}, "de": {"name": "Weiße Tassen mit goldenen Linien und dunklen Untertassen"}}}, {"id": "452ffcc8-ff1e-5daa-a41c-fdf4a9be31b2", "name": "أباجورة طاولة كريمية وذهبية بقاعدة مزخرفة", "description": "أباجورة بغطاء كريمي ذي نقوش دائرية وحواف ذهبية، وقاعدة مزخرفة بتفاصيل شفافة وذهبية.", "section": "ديكورات وهدايا", "image": "https://damascus-shop.com/images/happy-house/20261101/29907.jpg", "translations": {"en": {"name": "Cream and gold decorative table lamp"}, "de": {"name": "Dekorative Tischlampe in Creme und Gold"}}}]$products$::jsonb)
as r(id uuid,name text,description text,section text,image text,translations jsonb)
cross join public.stores s where s.id='c0a627c1-229d-4da9-957c-4aff3ff48a8f' and s.active and s.deleted_at is null
on conflict(id) do nothing;
commit;
